ProjectALife = ProjectALife or {}
ProjectALife.DialogueShards = ProjectALife.DialogueShards or {}
ProjectALife.DialogueShards["radio_6"] = {
{"r4_hor_funeral_cooler","caller_story_horror",3,8,0,4,1,{"Caller - Delbert","Delbert Crane - Crane and Sons, West Point, I've been the funeral director there thirty-four years","Marty","Mr. Crane, I know the name","Caller - Delbert","Friday we had two in the back for Monday visitations - Mrs. Beal, who passed in her sleep, and a young man brought in Friday evening","Caller - Delbert","The sheriff's deputy that brought him said heart attack, he said it fast - he didn't want to stay and sign","Caller - Delbert","I'd done my work on Mrs. Beal already, the young man I hadn't started, something told me to wait on him","Caller - Delbert","Saturday morning, the sheet on him was on the floor - and he was on his side, facing the wall, I did not put him on his side","Caller - Delbert","I locked the prep room, for a week I've heard him in there, walking into the steel table - walking into it and walking into it","Caller - Delbert","Tonight it's different, tonight I hear two sets of feet","Caller - Delbert","Mrs. Beal is still on her table under her sheet - I looked through the little window, so I don't know whose other feet those are","Caller - Delbert","That room has one door, Marty, I have the only key, it's been in my vest pocket all week","Marty","(Marty doesn't answer, something falls off his desk, and he doesn't pick it up)"}},
{"r4_hor_hospital_elevator","caller_story_horror",3,8,23,4,1,{"Caller - Luanne","I'm a unit clerk, I'm at home now, but I was at the hospital in Louisville Friday night and Saturday","Marty","How bad was it?","Caller - Luanne","I'm not calling about the ER, everybody's heard about the ER - I'm calling about the elevator","Caller - Luanne","Saturday morning the power went to generator, and the service elevator between floors stopped - with the doors shut, stuck between three and four","Caller - Luanne","There were people in it, a transport aide and a patient on a stretcher - you could hear them through the shaft doors, calling for maintenance","Caller - Luanne","We said hold on, someone's coming, all day we said it - and by afternoon the aide stopped calling","Caller - Luanne","And then there was a different noise in there, and the aide started calling again - screaming this time","Caller - Luanne","And then later, the elevator phone rang at the nurses' station - the little red one, and I picked it up","Caller - Luanne","Nobody said anything, just the receiver knocking against the wall of the car - swinging on its cord - knock - knock","Marty","(Marty exhales like he has been holding it, he says, I'm sorry, to nobody in particular)"}},
{"r7_mil_relay_through_a_deputy","military",3,6,0,23,2,{"Cardinal Main","Knox County, this is Cardinal Main, we have a working radio on your channel and nothing else - can you pass a message for us, over?","Dispatch","Cardinal Main, Knox County, I can pass it if somebody I can reach is standing where it needs to go","Cardinal Main","We need the barrier at the Otter Creek Road to know their relief is not coming tonight, over","Dispatch","I've got a deputy about two miles from there - Knox 22, did you copy the Army?","Knox 22","Knox 22 copies, I'll drive up there and tell them out of my own mouth","Cardinal Main","Knox County, tell your deputy to stop a hundred meters short and use his headlights, over","Dispatch","He heard you say it - Knox 22, a hundred meters and use your high beams","Knox 22","Copy - Cardinal Main, if you got anything you want told to them besides the bad part, now's the time","Cardinal Main","Tell them their company commander knows exactly where they are and has not forgotten them - word for word, over","Knox 22","Word for word - Knox 22 en route"}},
{"r7_mil_relay_readback_catches_it","military",3,6,0,23,1,{"Relay Two","Cardinal-1-6, Relay Two relaying for Main, your relief arrives at the barrier at zero four thirty - I say again, zero four thirty, over","Cardinal-1-6","Relay Two, read back zero fourteen thirty - confirm, over","Relay Two","Negative, negative, zero four thirty - four, as in four o'clock in the morning, over","Cardinal-1-6","Relay Two, you're breaking up on the numbers, send it a different way, over","Relay Two","Cardinal-1-6, your relief arrives two hours before the sun comes up - two hours before sunrise - how copy, over?","Cardinal-1-6","Good copy, two hours before sunrise - Relay Two, that's the only way anybody's said a number to me all day that stuck, over","Relay Two","Then I'll keep doing it that way - Relay Two, out"}},
{"r7_mil_auth_card_got_wet","military_mistake",3,6,0,23,1,{"Cardinal-1-6","Cardinal Main, 1-6, my authentication card went through the rain in my cargo pocket - the whole bottom half of it is blue smear, over","Cardinal Main","1-6, can you read any of it, over?","Cardinal-1-6","I can read the top three rows, everything past Lima is gone, over","Cardinal Main","Then challenge only out of the top three rows and tell your subordinates the same, over","Cardinal-1-6","Main, if anybody's been listening to this net, they just learned which rows I can read, over","Cardinal Main","Yes, they did. 1-6, go to a landline or a runner for anything that matters from here on, over","Cardinal-1-6","There's no landline in twelve miles and I've got one truck that runs, over","Cardinal Main","Then a runner - Cardinal Main, out"}},
{"r7_mil_deputy_asks_to_authenticate","military",3,6,0,23,1,{"Knox 20","Cardinal Main, this is the Knox County Sheriff's Office, unit Knox 20 - is there a way I can prove to your roadblocks that I'm me?","Cardinal Main","Knox 20, say again your request, over","Knox 20","My deputies are getting rifles pointed at them twice a night by scared soldiers - I want a word they can say - anything - a word","Cardinal Main","Knox 20, I can't give a civilian agency our authentication tables, over","Knox 20","Then make one up - pick a word - tell your checkpoints that a county car that says that word is a county car","Cardinal Main","Stand by, Knox 20","Cardinal Main","Knox 20, the word is Bluegrass, your cars say Bluegrass at the barrier and my people will hold their fire and come talk - over","Knox 20","Bluegrass, I copy Bluegrass - Cardinal Main, that's the most useful thing anybody's done for me since Friday","Cardinal Main","Knox 20, tell every one of your deputies tonight - not tomorrow - tonight - Cardinal Main, out"}},
{"r7_mil_medevac_refused_ceiling","military",3,6,0,23,1,{"Cardinal-3-6","Dustoff Operations, Cardinal-3-6, nine line follows, two urgent, both litter, one is a gunshot to the abdomen, over","Dustoff Operations","Cardinal-3-6, all aircraft are down - Ceiling's on the deck from the river to Elizabethtown and it's been that way since dark, over","Cardinal-3-6","Dustoff Operations, how long until you can fly, over?","Dustoff Operations","The weather people say morning, I'll tell you honestly, they told me morning yesterday too, over","Cardinal-3-6","Roger, then I need a ground route to a surgeon, over","Dustoff Operations","3-6, the nearest working operating room I know of is Elizabethtown, and they've been refusing everybody since noon, over","Cardinal-3-6","Then I'll take my own truck and they can refuse me at their own front door, face to face, over","Dustoff Operations","3-6, if you do that, tell them a flight crew sent you and give them my name - might buy you one minute of listening, over","Cardinal-3-6","Send your name, over","Dustoff Operations","Chief Warrant Officer Beckham, spell it like the town in Ohio County - Dustoff Operations, out"}},
{"r7_mil_medevac_ground_instead","military",3,7,0,23,1,{"Cardinal Main","All Cardinal stations, Cardinal Main with a change to medical evacuation - effective now, nine line requests go to me and not to Dustoff, over","Cardinal-1-6","Cardinal Main, 1-6 - say reason, over","Cardinal Main","Because the answer from Dustoff has been no for two days running and I would rather tell you no myself than have you wait on a helicopter, over","Cardinal-1-6","Roger - what can you actually send, over?","Cardinal Main","One ambulance out of the aid station and whatever five-ton is closest to you - that is all the air ambulance this battalion has left, over","Cardinal-1-6","Main, a five-ton with a man bleeding in the back is forty minutes of the worst ride of his life, over","Cardinal Main","I know what it is - put two soldiers in the bed with him and tell them to hold on to him with their hands - not with a strap, with their hands, over","Cardinal-1-6","Wilco. 1-6, out"}},
{"r7_mil_water_point_at_the_school","military",3,6,7,20,2,{"Cardinal-3-6","Cardinal Main, 3-6, I've set a water point in the bus lot at the elementary school - two trailers and a pump, over","Cardinal Main","3-6, roger - what's your rate, over?","Cardinal-3-6","Four hundred gallons an hour if the pump behaves, there's about three hundred people in this lot with jugs, over","Cardinal Main","3-6, are they orderly, over?","Cardinal-3-6","They're better than orderly, somebody organized a line with lawn chairs and a woman's writing down who's had their turn in a spiral notebook, over","Cardinal Main","Who organized it, over?","Cardinal-3-6","Nobody I put there, a retired schoolteacher - she's got a whistle around her neck and everybody in this lot does what she says, over","Cardinal Main","3-6, get her name and don't argue with her about anything - Cardinal Main, out"}},
{"r7_nights_no_answer_three_calls","scanner",3,5,0,5,2,{"Dispatch","Knox 26, Knox County","Dispatch","Knox 26, Knox County, it's been ten minutes since your last","Dispatch","Knox 26 - Buckner, if you can hear me, key up twice and don't say nothing","Knox 20","Knox 20, dispatch, what was his last traffic?","Dispatch","Traffic stop, 31W at the Fallas Lake turn - Kentucky plate, he read it to me and I never got a return on it","Knox 20","Knox 20 en route from Muldraugh, start Kidwell too, and start him from the other end","Knox 26","Knox County, Knox 26","Dispatch","Go ahead, 26, go ahead","Knox 26","I'm all right, car's empty, driver's gone, purse in the seat - I set my mic down and forgot I set it down - that's all it was","Dispatch","That's all right, 26 - that's fine, I'm gonna need a minute here"}},
{"r7_nights_water_plant_alarm","scanner",3,5,1,5,1,{"Dispatch","Knox 24, alarm at the water plant off Otter Creek Road - the alarm company's calling it in from Louisville","Knox 24","Knox 24 en route - is anybody supposed to be out there this time of night?","Dispatch","The night man, he don't answer his phone and the company says that door's been open eleven minutes","Knox 24","Knox 24 on scene, gate's pushed in, there's a truck here with the driver's door standing wide open","Dispatch","Any sign of the night man?","Knox 24","There's a lunch box on the step and a thermos poured out on the concrete - dispatch, if this plant quits, who is it we call?","Dispatch","I don't know, 24, the county judge, I reckon, I'll start looking up numbers","Knox 24","Look 'em up, tell whoever answers the pumps are still running and the man that runs them ain't here"}},
{"r7_nights_courthouse_deed_books","scanner",3,6,1,5,2,{"Dispatch","Knox 22, burglar alarm at the courthouse, rear door, the clerk's side","Knox 22","Knox 22, show me that way, third time this week for that door","Dispatch","It ain't the wind this time, the janitor's on the phone and he says he can hear somebody moving in the clerk's office","Knox 22","Knox 22 on scene, glass is out of the door, dispatch, I need a second unit and this time I'm gonna wait for it","Knox 20","Knox 20, two minutes out","Knox 22","Knox 20, be advised, they ain't in there for money - they're in the records room","Knox 20","Records room, say again?","Knox 22","Deeds, Sarge, somebody's in there with a flashlight going page by page through the deed books"}},
{"r7_nights_went_in_alone","scanner",3,5,22,4,2,{"Knox 20","Knox 24, Knox 20 - where are you at right now?","Knox 24","Knox 24, I'm in the driveway at 78 Linden Street - I already went in, Sarge","Knox 20","You went in by yourself","Knox 24","There was a girl screaming in there, I ain't gonna sit on the road and listen to that with my hands in my lap","Knox 20","Is she out?","Knox 24","She's out, she's in my front seat with my jacket on her and she ain't hurt","Knox 20","Then we'll argue about the rule at breakfast - Knox 20 en route to you","Knox 24","Copy - Sarge, I'd do it again","Knox 20","I know you would, that's the part I'll lay awake on - Knox 20 out"}},
{"r7_nights_dispatcher_twenty_one_hours","scanner",3,6,4,8,1,{"Knox 20","Knox County, Knox 20 - is Hazel coming in at six?","Dispatch","Hazel ain't coming - Tree's across her road and she's got nobody to watch her girls","Knox 20","How long have you been in that chair, Bonnie?","Dispatch","Since yesterday morning","Knox 20","That's nineteen hours","Dispatch","It's twenty-one, I done the math about an hour ago and then I quit doing math","Knox 20","Knox 22, swing by the office and bring her whatever's left in that machine","Knox 22","Knox 22 copies - Bonnie, you want the peanut butter crackers or the other kind?","Dispatch","The other kind, and 22, bring me a chair that's got a back on it if you can find one"}},
{"r7_nights_order_read_to_shift","scanner",3,4,20,23,2,{"Knox 20","All Knox units, stand by for traffic, I'm reading this once and then it lives on the wall at the office","Knox 20","By order of the county judge and the Army at Fort Knox, no travel on US-31W north of Muldraugh after dark - that's everybody - us included","Knox 20","Any citizen at a roadblock gets told to turn around and go home - we are not to argue with the soldiers about it","Knox 22","Knox 22, what if home is north of Muldraugh?","Knox 20","Then the order gives me a shelter address, and the shelter's full - I don't have a better answer than that one","Knox 24","Knox 24, does it say what we do if they don't turn around?","Knox 20","It says use your discretion, which means it don't say - all units acknowledge","Knox 22","Knox 22 copies","Knox 24","Knox 24 copies, and I want it in the log that I asked the question"}},
{"r7_ksp_close_the_crossovers","scanner",3,4,6,12,1,{"Post 4","All units, Post 4 - Highway Department is closing the median crossovers on both parkways as of noon today","Trooper 418","Post 4, 418 - all of them?","Post 4","All of them, concrete barrier where they can get it there, gravel and a dump truck where they can't","Trooper 418","Then if I'm eastbound and the call's westbound, my turnaround is what, twelve miles?","Post 4","Nine at the Leitchfield exit and nineteen past that, I know it, plan your day accordingly","Trooper 422","Post 4, 422 - who asked for this?","Post 4","It came down as a written order and it's signed by a colonel, not by anybody I can call up on the phone"}},
{"r7_ksp_forty_miles_one_trooper","scanner",3,5,14,23,1,{"Trooper 422","Post 4, 422 - give it to me straight - who else is on the parkway with me right now?","Post 4","Nobody, 422, from the Elizabethtown ramps to the Ohio County line, that's you","Trooper 422","That's about forty miles of two-lane each way","Post 4","Forty-one, I measured it this morning on the wall map with a piece of string, since we're being honest","Trooper 422","All right, then I'm going to run the middle of it and I'll come when somebody hollers","Post 4","That's about all any of us can offer. 422, key up every thirty minutes even if you've got nothing to say","Trooper 422","Every thirty, copy that, Post 4"}},
{"r7_ksp_ramp_closed_by_county","scanner",3,5,7,20,1,{"Trooper 418","Post 4, 418, somebody has put two combines across the parkway ramp at the county road and chained them together","Post 4","418, who did?","Trooper 418","Farmers, four or five of them stood there with shotguns and one of them's got a lawn chair - they say nobody comes off the parkway into their end of the county","Post 4","Have they threatened anybody?","Trooper 418","They offered me a cold drink, that's about as far as it went","Post 4","Then leave it be for now and write it up - I'd rather they blocked a ramp than a road somebody lives on","Trooper 418","Copy, post 4, they wanted me to tell you the chain's their own and they'd like it back after"}},
{"r7_ksp_shots_at_the_fence","scanner",3,6,13,23,1,{"Trooper 422","Post 4, 422, somebody's shooting from the woods on the south side of the parkway right about milepost 101","Post 4","422, shooting at traffic?","Trooper 422","Negative, they're shooting at the right of way fence - there's a bunch of them up against that fence walking east and somebody's picking at them from the trees","Post 4","How many is a bunch?","Trooper 422","Sixty, seventy, they're strung out along that fence line like cattle on a hot day, and they all turn when a round goes off","Post 4","422, do not engage and do not stop in that stretch","Trooper 422","Copy, post 4, whoever's in them trees is going to bring that whole fence line down on top of himself and he don't know it"}},
{"r7_ksp_wrecker_wont_roll","scanner",3,5,9,21,1,{"Post 4","Trooper 435, I've called every wrecker on the rotation, two didn't answer and one told me to go to hell, politely","Trooper 435","Which one was polite about it?","Post 4","The man out of Cecilia, he said his driver got bit at a wreck Tuesday and he's got nobody left that'll go out on the parkway","Trooper 435","Copy, then I'm going to push this car off the road with my bumper and I'll take whatever damage the state wants to charge me","Post 4","435, that's a way to end up walking","Trooper 435","Post 4, there's a car in the eastbound lane on a curve and it's getting dark - somebody's going to hit it at sixty-five","Post 4","Go ahead and push it, I'll write that I ordered it, and I did order it, so that's not a lie either"}},
{"r7_ksp_checkpoint_liaison","scanner",3,5,8,20,1,{"Post 4","Trooper 422, the Army wants a state trooper at the 31W roadblock at Muldraugh - they say civilians will listen to a Kentucky uniform","Trooper 422","422 copies - what's my authority out there?","Post 4","You're there to talk, you don't give their orders and you don't take their orders","Trooper 422","And if a family drives up wanting to go north to their own house?","Post 4","Then you tell them no, and you tell it in your own words instead of his, and that's the only reason they want you standing there","Trooper 422","Post 4, that's the worst assignment I've had in nineteen years","Post 4","I know it - take a case of water out of the post with you - you'll hand out more of that than anything else"}},
{"r7_ksp_detective_takes_a_cruiser","scanner",3,5,7,15,1,{"Post 4","All units, be advised, Detective 7 is in a marked car today - if you see a man in a necktie driving a cruiser, that's him","Trooper 406","406, copy - post 4, what happened to his car?","Post 4","It's in the garage with the rest. 406, he's got eleven open cases and nine of the complainants are dead, so he's driving a cruiser and answering calls","Trooper 406","Does he remember how?","Post 4","He wrote traffic for six years before he made detective - he'll be fine - be nice to him","Trooper 406","406 copies, I'll be real nice to him - I'll even let him take the first call at a school"}},
{"r7_fire_tower_at_eight_feet","scanner",3,5,6,22,1,{"Dispatch","Car 3, the water plant finally answered, the man says the tower's down to about eight feet","Car 3","Eight feet out of how much?","Dispatch","He said it holds thirty-two when it's right, he also said don't quote him, he's been reading the gauge with a flashlight","Car 3","Dispatch, does the town know?","Dispatch","Nobody's told them, the water's still coming out of their taps, so as far as anybody knows it's fine","Car 3","Then somebody needs to get on the radio station and tell folks to fill every jug they own tonight","Dispatch","Car 3, if we say that on the air, everybody in the county turns a tap on at the same minute","Car 3","I know it - say it anyway, I'd rather they had it in their kitchens than in a tower we can't reach"}},
{"r7_fire_tones_and_nobody","scanner",3,5,0,23,1,{"Dispatch","Station 33, Station 33, structure fire, 16 Wickham Street - time out {time}","Dispatch","Station 33, second page, structure fire, 16 Wickham Street","Dispatch","Station 33, third page, anybody at Station 33, key up","Engine 33","Dispatch, Engine 33, I'm here by myself and I can't roll a pumper by myself","Dispatch","Engine 33, how many showed?","Engine 33","Me - Otto's wife called and said he's sick, two of them are at the shelter with their families and one of them I ain't seen since Friday","Dispatch","Engine 33, do you want me to page the county?","Engine 33","Page whoever you want, dispatch, take Station 33 out of service - write it down so nobody sends a family's house to us and then waits"}},
{"r7_fire_church_full_of_people","scanner",3,5,18,23,2,{"Dispatch","All fire units, Little Bethel church on Tanner Road, smoke showing from the fellowship hall - they've got people sleeping in there","Car 3","Car 3 en route - dispatch, how many people?","Dispatch","Preacher said forty last night, he's the one calling and he's got them out in the parking lot","Car 3","All of them out?","Dispatch","He says he counted forty-one and he counted twice, and he says he'd like somebody to tell him whether forty-one is right","Car 3","Tell him forty-one is right, tell him a baby came in Tuesday night and nobody put it on his list","Dispatch","Car 3, he's asking about the building","Car 3","The building's a stove and a coffee pot in a kitchen with a bad wire - I'll save the building, he already saved the part that matters"}},
{"r7_ems_pickups_as_ambulances","scanner",3,5,6,23,1,{"EMS 1","All units and anybody with a scanner on, EMS 1 with an announcement, and I'd like the radio station to pick this up if they're listening","EMS 1","If you have got a person hurt and you've got a truck, put them in the truck and drive them yourself - do not wait on an ambulance","EMS 1","Put a blanket under them, two people in the bed with them, one at the head, and don't let anybody ride sitting on the tailgate","Dispatch","EMS 1, are you sure you want that on the air?","EMS 1","Dispatch, I've got two ambulances for a county this size and one of them's got a bad door - yes, I'm sure","EMS 1","And when you get to the hospital, don't blow the horn and don't leave your truck in the ambulance bay - somebody's coming behind you"}},
{"r7_ems_oxygen_out","scanner",3,5,0,23,1,{"Medic 3","Hospital, Medic 3, I'm down to one oxygen bottle and it's half - can I swap at your dock?","Hospital","Medic 3, negative, we're feeding our own patients off portables and the supply truck didn't come Monday or Thursday","Medic 3","Hospital, I've got a woman with congestive heart failure I've carried three times this month","Hospital","I know her - Bess on Pine Street","Medic 3","That's her - what do I do?","Hospital","Sit her up, keep her cool, and stay with her as long as you can stay - that's the medicine we've got left, Medic 3","Medic 3","Copy, hospital, she asked me to tell somebody her cat's shut in the back bedroom","Hospital","Tell her I wrote it down, I did write it down"}},
{"r7_ems_medic_got_bit","scanner",3,5,0,23,2,{"Medic 3","Dispatch, Medic 3, I need you to go off the air with everybody else and just talk to me a minute","Dispatch","Go ahead, Medic 3","Medic 3","My partner got bit at the last call, forearm, through the sleeve, it's about two inches and it's bleeding good","Dispatch","Medic 3, where are you?","Medic 3","Pulled over at the fire hall lot on 31W, he's sitting on the bumper with a pressure dressing on it and he's real calm, which is worse","Dispatch","Do you want the hospital?","Medic 3","The hospital can't do a thing and he knows it better than I do - he's been running this rig eleven years","Dispatch","Medic 3, what do you want me to do?","Medic 3","Take us out of service and call his wife and tell her he's coming home - don't tell her the rest, he wants to say it himself"}},
{"r7_ems_er_nurse_takes_the_mic","scanner",3,6,20,5,1,{"Hospital","Anybody on the EMS channel, this is the charge nurse at Knox County - I'm going to read something and then I'm going to hang the mic back up","Hospital","We have forty-one patients, nine beds, two nurses and an orderly - the elevator's been stuck between floors since Tuesday","Hospital","If you bring us somebody, bring their name written down - we have quit being able to ask people their names","Hospital","If you bring us somebody with a family, keep the family - we don't have anywhere to put a person who isn't hurt","Hospital","And if you're a nurse listening to this at home, come in - come in, or call, or send word, or anything at all","Hospital","That's it, that's what I had to say - Knox County Hospital, clear"}},
{"r7_ems_baby_in_a_driveway","scanner",3,6,2,8,1,{"Medic 3","Dispatch, Medic 3 - show me on scene at 1204 Halbert Street, and show me on scene for a while","Dispatch","Medic 3, what have you got?","Medic 3","I've got a lady having a baby in the front seat of a Buick in her own driveway, and I've got about four minutes of experience at this","Dispatch","Medic 3, do you want me to find you a nurse on the phone?","Medic 3","Find me anybody, stay on the radio with me","Medic 3","Dispatch, stand by","Medic 3","Dispatch, show one more person in Knox County at {time} - girl, she's hollering, which I'm told is the good outcome","Dispatch","Medic 3, say that again for the log?","Medic 3","One more person in Knox County at {time}, her mama says the name's going to be Ruth after her own mother - put that in the log too"}},
{"r7_school_evacuate_the_gym","scanner",3,4,10,18,2,{"Base","Base to all buses, we are emptying Muldraugh Elementary this afternoon - everybody out of the gym and out of the cafeteria","Bus 12","Bus 12, Base, say again? We just spent two days filling it","Base","I know what we spent two days doing, the order came from the county and the county got it from the Army at the checkpoint","Bus 7","Bus 7, where are we taking them?","Base","The staging area at the fairgrounds on 31W, and from there somebody else is supposed to move them - that's all I know and I asked three times","Bus 12","Base, how many are in that gym?","Base","Two hundred and ten this morning, bus 12, you'll make four trips and 7 will make four and I'll drive one myself","Bus 7","Base, you ain't drove a route in nine years","Base","Then it'll be a slow trip and everybody on it will be alive at the end - pull them up to the doors"}},
{"r7_school_bus12_loading_count","scanner",3,4,11,19,1,{"Bus 12","Base, Bus 12 loaded at the gym doors, I've got sixty-six aboard on a bus rated for seventy-two kids, which ain't the same as sixty-six grown people","Base","Bus 12, are you safe to roll?","Bus 12","I'm safe to roll slow, base, there's nine standing in the aisle and one in the well by my door","Base","Get the one out of the well, that's the one thing I'll be firm about","Bus 12","He's an old fella and he says if he gets off he ain't getting back on","Base","Then put him in my seat behind you and you drive standing up if you have to - just get him out of the door well","Bus 12","Copy, base, this is the fullest this bus has ever been and I've drove it since 1981"}},
{"r7_school_bus7_wrong_turn","scanner",3,4,12,20,1,{"Bus 7","Base, Bus 7, I'm turned around - they've got 31W blocked at the fairgrounds road and a soldier waved me north","Base","Bus 7, do not go north, whatever he waved, do not go north","Bus 7","I already went north, Base, I'm about a mile up with sixty people on this bus and no place to turn around","Base","Bus 7, is there a church on your right with a gravel lot?","Bus 7","I see it - Cedar Grove","Base","Swing in there, use the whole lot, and come back south - and Bus 7, stop at the block and make that soldier look at you when he waves","Bus 7","Base, he's about nineteen and he's waving with both arms at everything that moves - I don't think he knows which way is which either"}},
{"r7_school_kids_with_nobody","scanner",3,5,12,21,2,{"Bus 12","Base, Bus 12, I've got four kids on this bus with no grownup attached to them","Base","Bus 12, do they know their names?","Bus 12","Three do, the little one just says Bubby and holds up two fingers when I ask him how old","Base","Write down everything each one tells you, name, street, mama's name, the dog's name, anything at all","Bus 12","I'm writing it in the attendance book, that's the only paper on this bus","Base","The attendance book is exactly right, bus 12, don't let anybody take a child off that bus at the fairgrounds unless they write their own name in it too","Bus 12","Copy, base, the three big ones have took charge of the little one - they put him in a seat between two of them and they buckled him in","Base","Then write their names down first, Bus 12 - write those three down first"}},
{"r8_hor_coffee_still_warm","caller_story_horror",3,30,0,4,1,{"Coy","You can cut me off if this is nothing, I honest to God can't tell anymore","Coy","Farmhouse on Echo Creek Road - Tuesday, about four in the afternoon, door stood open and there wasn't a speck of dust on that floor","Coy","There was coffee in the pot and it was warm - warm, on a dead stove","June","Was a generator running somewhere on the place?","Coy","I checked the shed, I checked the meter, nothing turning anywhere on that farm - I put my hand flat on the pot twice","Coy","Slept in the truck with the doors locked, I'm a man never locked a door in his life","June","Did you go back?","Coy","For what? So I'd find out? No ma'am"}},
{"r8_hor_turn_signal_ditch","caller_story_horror",3,40,0,5,1,{"Nadine","Truck in the ditch at the Carver bridge end, nose down in the weeds","Nadine","Been there, everybody's seen it, dome light's been dead a week, battery's flat, you can hear it's flat when you try the horn","June","So what changed?","Nadine","The turn signal's going - left one - ticking, you can hear it from the road at night, tick, tick, tick","Nadine","A flat battery don't run a blinker, my daddy was a mechanic thirty-one years, and I know that much","June","I'm not going to guess at it","Nadine","I don't want you to guess, I want somebody else to walk down there in the daylight and tell me they hear it too","Nadine","It's signaling a left turn, into the field, there's nothing over there but the field"}},
{"r8_hor_lights_block_by_block","caller_story_horror",3,20,23,5,2,{"Maxine","I watched the city go dark off my roof - Louisville, I mean, you can see the glow from our hill","June","Which night?","Maxine","The tenth, I got up there about eleven with a quilt, 'cause I knew it was coming - everybody knew","Maxine","It didn't go all at once","June","No?","Maxine","Block by block, north end first, then the next piece, then the next - working down toward the river","Maxine","Took near two hours, and it was steady - same pace the whole way, like a man walking a fence and throwing switches","June","Something was walking it","Maxine","I didn't say that, you said that - but yeah","Maxine","When it got down to the last of it I went inside - I have never in my life - never, anyway, that's what I saw and I've not told it before"}},
{"more_radio_school_picture","caller_story_sad",4,3650,0,23,1,{"Edith","I found a school picture in my coat","June","One of your pupils?","Edith","One from years ago, he'd drawn a mustache on himself","June","A good one?","Edith","Terrible - green crayon, reached both ears","Edith","I said, 'You're getting that on your fingers.' That's what I remember saying","Edith","He gave it to me and said I'd recognize him when he grew up","Edith","I don't-- sorry, I don't even know how old he'd be now","Edith","Old enough for a real mustache, I hope, a bad one","June","You can take a minute, I'm still here"}},
{"more_radio_roofer_gravity","caller_joke",4,3650,0,23,1,{"Wade","My apprentice once asked why we couldn't roof from underneath","June","Out of the sun?","Wade","That was his thinking","Wade","He was dead serious - 'wouldn't it be cooler under there?'","Wade","So I told him, go on then, nail a shingle to the sky","June","Wade, you didn't","Wade","Well, not those words, there were a few more in it","June","I can guess which ones","Wade","Good kid, terrible roofer - excellent lunch companion","Wade","He'd always bring too much lunch, said his mother couldn't count"}},
{"king_radio_pencil_name","caller_story_sad",4,3650,0,23,1,{"Cal","I practiced writing my name today","June","For a reason?","Cal","I hadn't signed anything in a while. Looked strange","June","Did it come back to you?","Cal","The last letter still leans the wrong way","June","Sounds like yours, then","Cal","Yeah. That's what I thought","June","I'm glad there's something that still does"}},
{"king_radio_rumor_caution","rumor",4,3650,0,23,1,{"June","There's another story going around about a place handing out supplies","June","I haven't spoken to anybody who has actually been there","June","So I don't have a place to send you","June","I won't dress that up as directions","June","If you've got a firsthand report, we can listen","June","Please say when you were there, too","June","I want it to be true as much as you do","June","Wanting it isn't enough"}},
{"king_radio_hard_name","obituary",4,3650,0,23,1,{"Ada","I'd like to say a name, but I don't want to say they're dead","June","Then we won't say that","Ada","Daniel. He hated Dan","June","Daniel","Ada","He'd correct you even when he was half asleep","June","What else would you like us to know?","Ada","That he mattered. That's enough for today","June","All right. Thank you for telling us about Daniel"}},
{"king_radio_address_book","caller_story_sad",4,3650,0,23,1,{"Nell","I found my old address book. Half the people in it had already moved","June","Did you keep up with them?","Nell","Christmas cards. Sometimes not even that","June","I'm sorry","Nell","It's the crossed-out addresses that get me. They could be anywhere","June","They could","Nell","I'm not crossing out any more names","June","You don't have to"}},
{"king_radio_bad_coffee","caller_joke",4,3650,0,23,1,{"Sal","I made coffee so bad I apologized to the cup","June","Did it accept?","Sal","No. Cracked right down the side","June","Might've been something else","Sal","You weren't there, June","June","Fair point","Sal","I'm sticking to water. Cup's had enough","June","Sounds like you have too"}},
{"king_radio_quiet_is_not_empty","host",4,3650,0,23,1,{"June","Sometimes the line stays quiet longer than I'd like","June","I start thinking I should say something just to fill it","June","That's when I say things twice. You've probably noticed","June","I'm trying not to guess who's still out there","June","No answer doesn't tell me enough","June","You might be busy. You might not want to talk","June","That's all right","June","I'll leave you a little quiet before I go on"}},
{"knox_key_ring","caller_story_sad",4,3650,0,23,1,{"Walt","Anybody else still carry their house keys?","June","I do","Walt","There's no good reason I need mine anymore, still check for them every time I stand up","June","Some habits are the last pieces of a place we get to keep"}},
{"knox_hoarse_host","host",4,3650,0,23,1,{"June","If I sound angry, I'm not angry with you, my voice is tired","June","I used to spend all day wishing people would stop talking","June","Turns out I only meant particular people","June","Anyway, there's room on the air if you need it"}},
{"r1_d4_repeater_on_batteries","scanner",4,4,5,11,1,{"Dispatch","All Knox units, the tower repeater at West Point lost commercial power overnight - it's running on battery backup","Dispatch","Keep your traffic short, when the batteries go, you'll only reach me car-to-car if you're close by","Knox 9","Knox 9 - how long on the batteries?","Dispatch","The radio shop said eight hours on a good day - the radio shop isn't answering the phone to tell me what a bad day is","Knox 9","Copy, short traffic, love you, Linda - bye","Dispatch","That was not short, Knox 9"}},
{"r1_d4_count_by_number","scanner",4,4,16,21,2,{"Dispatch","Knox County, for the log, at {time}, the coroner has not checked in today","Dispatch","I'm going to keep his count, anyone who found deceased today, give me a number, not an address - just a number","Knox 11","Knox 11 - nine","Knox 20","Knox 20 - fourteen","Hardin 12","Hardin 12 - six, and one dog","Dispatch","Copy, I'll count the dog","Knox 9","Knox 9 - three - Linda, one of them was the coroner, on his front porch swing - I'm sorry","Dispatch","Copy - three","Dispatch","Total for today, thirty-two, and the dog - log's closed"}},
{"r1_d4_tuesday_noon_tone_test","scanner",4,4,12,12,3,{"Dispatch","(Alert tones.) This is a test of the Knox County fire alerting system - this is only a test","Dispatch","It's noon on Tuesday, the console sends this test every Tuesday at noon, and I never did figure out how to shut it off","Dispatch","So I'm going to read the rest of the card - Muldraugh Fire, West Point Fire, Riverside Fire, Rosewood Fire, acknowledge the test","Station 21","Station 21, Muldraugh, acknowledges, twenty-six civilians and one cook also acknowledge","Dispatch","West Point Fire","Tanker 41","Tanker 41 for West Point, what's left of it acknowledges - tell the card we passed","Dispatch","Riverside Fire","Dispatch","Rosewood Fire","Dispatch","End of test, same time next week"}},
{"r1_d4_tanker41_pager_tuesdays","scanner",4,4,12,17,1,{"Tanker 41","Tanker 41 to Knox County, my pager went off for that noon test and I about came out of my skin","Dispatch","Sorry, 41","Tanker 41","Don't be, first time it's gone off in three days, felt like somebody still wanted me someplace","Tanker 41","West Point Fire is me, this tanker, and two boys from the high school football team who can pull hose","Dispatch","Do you need anything?","Tanker 41","No, keep that test going on Tuesdays - that's all I wanted to say"}},
{"r1_d4_knox20_march_ridge_sweep","scanner",4,4,8,15,2,{"Knox 20","Knox 20 to Knox County, I've done a sweep of March Ridge, I'll give you the houses with people in them - take it down","Knox 20","Pruitt Lane, the brick two-story with the basketball goal, bedsheet in the upstairs window - says four inside, out of water","Knox 20","Oak Ridge Court, the house with the big yellow dog - family's still inside, the dog is out in the yard, standing guard","Knox 20","Laurel Drive, the split-level with the swing set, somebody wrote HI POLICE in sidewalk chalk on the driveway - little hands waving in the front window","Knox 20","Hawthorne, the blue trailer at the end, old man on the porch with a shotgun told me to get off his property - he's doing fine","Dispatch","I've got all four, water for Pruitt Lane - I'll see who can carry some","Knox 20","None of them would open a door for me, every one of them said the same thing - tell the radio lady hello","Dispatch","Hello back, March Ridge"}},
{"r1_d4_knox9_bucket_on_rope","scanner",4,4,10,17,1,{"Knox 9","Knox 9 to Knox County, I'm on Pruitt Lane with two five-gallon jugs from the Station 21 tank","Knox 9","They won't open the door, and I don't blame them - they're lowering a mop bucket out the upstairs window on a clothesline","Dispatch","Is that going to hold five gallons?","Knox 9","It's going to hold about two at a time, we're on trip four, the line's squeaking something awful","Knox 9","Dispatch, it's the same girl from the bathroom call on Friday night - she yelled down my name - deputy Ames, she remembered it","Dispatch","Well, you told her to","Knox 9","Last trip's up, she sent the bucket back down with a peanut butter sandwich in it - I'm eating it in the car"}},
{"r1_d4_hardin12_bo_car_seat","scanner",4,4,9,17,1,{"Hardin 12","Hardin 12, Knox County, I'm headed your way with Medic 3's crew, the mother and the baby, and a police dog","Dispatch","Bo got in your car?","Hardin 12","He got in when the baby cried, walked right over and laid down against the car seat","Dispatch","I guess that's his job now","Hardin 12","I guess so - ETA twenty minutes, the crew wants to know if the cook's got supper","Dispatch","Station 21 says meatloaf - with onions"}},
{"r1_d4_janet_asks_about_bo","scanner",4,4,17,22,1,{"Dispatch","All Knox units, Janet Pratt is here at the console - she'd like to ask something - go ahead, Janet","Janet","Hi, this is Wayne's wife - Bo's been lying against the basement door since Russ brought him in - he won't eat","Janet","Wayne did all the feeding, I don't even know how much he gets - does anybody know how Wayne fed him?","Knox 9","Knox 9, Janet here - cup and a half at six and six, and Wayne always wet it with a little warm water","Knox 20","Knox 20, and he'd sit down on the floor next to the bowl while the dog ate - every time, said Bo wouldn't eat alone","Janet","Warm water - okay, I'll sit with him","Janet","Thank you - that's all, that's all I needed"}},
{"r1_d4_knox4_otter_creek_ramp","scanner",4,4,6,13,3,{"Knox 4","Knox 4 to Knox County - anybody still listening?","Dispatch","Knox 4! Go ahead, Knox 4!","Knox 4","I'm at the Otter Creek boat ramp, out of gas, portable battery's about gone - spent the night in the car, I never found the dog","Dispatch","The dog came home yesterday, he's in the basement with Donna","Knox 4","Course he did","Knox 4","Tell Donna I'm on foot, it'll be dark by the time I'm home... and she is NOT to let him out!","Dispatch","I'll tell her - stay off the main road, Knox 4","Knox 4","10-4, and Linda, tell him it's his turn to come find me"}},
{"r1_d4_muldraugh3_picks_up_knox4","scanner",4,4,11,18,1,{"Muldraugh 3","Muldraugh 3 to Knox County, I've got a sheriff's deputy walking up 1638 carrying his boots in his hand","Dispatch","That'll be Knox 4 - is he alright?","Muldraugh 3","Blisters, he says the boots were new - he's in my passenger seat drinking my water","Knox 4","Knox 4, on Muldraugh's radio - tell Donna I got a ride","Dispatch","She's standing right behind me, Knox 4, she heard you","Knox 4","Then tell the dog he's still in trouble","Dispatch","The dog says he's sorry - Donna says he isn't"}},
{"r1_d4_knox9_water_tower_view","scanner",4,4,6,11,1,{"Knox 9","Knox 9, I'm up the West Point water tower with binoculars, highest place in the county I can get to","Knox 9","North toward the river there's smoke over Louisville, four big columns, I can't see the bridges for it","Knox 9","South on 31W, the Army line's lit up - Floodlights all the way across, trucks behind them","Knox 9","Town's quiet, maybe a hundred of them on Main Street, just standing in the road - not going anywhere","Dispatch","Any people?","Knox 9","There's laundry on a line behind the Methodist church, somebody hung it out this morning - that's people","Dispatch","I'll log it, laundry on the line","Knox 9","Coming down now, my knees are going to tell me about it"}},
{"r1_d4_post4_last_scheduled","scanner",4,4,8,18,2,{"Post 4","Post 4 to all units, this will be the last scheduled broadcast from Post 4","Post 4","The generator is out of diesel - Remaining personnel are moving to the Army staging area at their direction","Post 4","Troopers in the field, you are released to act on your own judgment - protect life - keep your notes, someday somebody's going to ask","Trooper 435","435, Irvington school - copy all, it's been good working with you, Post","Trooper 422","422, same - tell the Commander we held as long as there was anything to hold","Post 4","Post 4, clear"}},
{"r1_d4_carla_keeps_the_radio","scanner",4,4,13,19,2,{"Unknown","Is anyone on this? I found this radio in a police car on Main Street in Rosewood","Dispatch","This is the Knox County Sheriff's Office - are you hurt?","Unknown","No, there's six of us in the pharmacy - we took the radio because the car was just sitting there with the door open","Dispatch","That's fine - keep it - what's your name?","Carla","Carla - is that allowed? Keeping it?","Dispatch","Carla, as of right now that radio is deputized - keep it with you - turn it on at the top of each hour and off after","Carla","Top of every hour - okay - somebody's knocking, not the kind of knocking you answer, I'll call at nine","Dispatch","Nine o'clock, Carla, I'll be here"}},
{"r1_d4_carla_nine_oclock","scanner",4,4,21,21,1,{"Carla","Knox County? It's Carla - it's nine, I think it's nine - the pharmacy clock stopped","Dispatch","It's nine, Carla - go ahead","Carla","Still six of us, the knocking stopped around seven - we found the cough syrup and the good flashlights","Dispatch","Stay away from the front glass tonight, sleep behind the counter where the shelves are","Carla","We're back there already. Made beds out of the greeting card boxes. All these cards telling us to get well soon","Dispatch","Get some rest, then. Call again at ten, Carla"}},
{"r1_d4_knox6_motel_on_rosewood_road","scanner",4,4,16,23,2,{"Knox 6","Knox County, Knox 6 - Officer needs assistance at the motel on Rosewood Road - hurry - please","Dispatch","Knox 6, I know your voice, nobody is coming to that motel","Knox 6","Aw, I said please and everything","Knox 6","Found your channel two, lady, it's the knob with the little numbers on it","Knox 20","Knox 20 to all units, that motel is a trap - stay off Rosewood Road","Knox 6","Sarge, you're no fun at all, we got beds - we got a pool, water's a little green","Dispatch","All units, go to the other frequency we talked about at the courthouse - don't say which one on the air","Knox 6","Bye, lady, we'll be listening"}},
{"r1_d4_air1_crew_walking","scanner",4,4,7,17,1,{"Air-1","Air-1 on the mutual aid channel, to anybody who can hear","Air-1","This is the crew of Air-1, we're on foot, headed south on Dixie with a few Second District officers","Air-1","If any pilot hears this, our aircraft is sitting on second base at the high school ball field - the key is under the seat","Air-1","She's got about ten minutes of fuel, enough to get somebody out of a bad spot - not enough to get anybody out of the county","2-Adam-14","2-Adam-14, air-1, you said second base on Sunday - is she still there?","Air-1","Walked past an hour ago - she's there, there's a kid sitting in the pilot seat, pretending to fly her - I let him"}},
{"r1_d4_hardin_dispatch_ugly_ones","scanner",4,4,10,20,3,{"Hardin Dispatch","Hardin County to Hardin 12, if you can hear me","Hardin 12","Hardin 12, go ahead, you're weak but readable","Hardin Dispatch","Russ, the Army says units on your side of the line stay on your side of the line - we asked them twice","Hardin 12","I figured - did you get hold of Carol?","Hardin Dispatch","She's here at the office, she's been here since Sunday, she wants me to tell you the tomatoes came in","Hardin 12","Tell her pick them before the birds do","Hardin Dispatch","She says she already did, she says she's saving you the ugly ones - you like those","Hardin 12","I do - tell her I'm helping people over here - tell her it's good work","Hardin Dispatch","You're breaking up, 12","Hardin 12","Tell her the ugly ones"}},
{"r1_d4_ems1_adams_motorcycle","scanner",4,4,7,13,1,{"EMS 1","EMS 1 to Knox County, with an update on the patient I carried out of the ICU on Sunday","Dispatch","Go ahead","EMS 1","He's breathing on his own this morning, we pulled the tube at Station 21, on the kitchen table","EMS 1","First thing he did was ask if his motorcycle was totaled","Dispatch","And you told him what?","EMS 1","I told him yes, he cried harder about that motorcycle than anything else, I think that's a good sign","EMS 1","Anybody who passes the hospital, the nurses on the third floor are still up there - if you find a way, he'd like to tell them thank you"}},
{"r1_d4_muldraugh3_eleven_laps","scanner",4,4,6,18,1,{"Muldraugh 3","Muldraugh 3 to Knox County - Muldraugh PD is in service","Dispatch","Morning, Muldraugh 3 - who's with you?","Muldraugh 3","Nobody - Muldraugh PD is me, I've got the chief's keys and the chief's coffee maker","Muldraugh 3","I'm running the town like a patrol beat - Main to Dixie, Dixie to the bypass, and back, I tap the horn twice at the houses where I know somebody's in","Dispatch","Do they answer?","Muldraugh 3","Some honk back - Mrs. Deering flicks her porch light, the boy in the apartment over the barber shop waves a flag","Muldraugh 3","Every lap I count them, every lap I'm hoping for the same number","Dispatch","What's the number this lap?","Muldraugh 3","Eleven, same as last lap - Muldraugh 3 is starting another one"}},
{"r1_d4_knox7_end_of_watch","scanner",4,4,9,17,2,{"Knox 20","Knox 20, Knox County, I went back by Knox 7's house on Walnut","Dispatch","Go ahead","Knox 20","I took care of it, he'd have done the same for me","Knox 20","His uniform's hanging on the bathroom door - pressed, he'd ironed it for Monday","Dispatch","Copy, Knox 20","Knox 20","Mark Knox 7 end of watch - put down that he argued","Dispatch","Knox 7, end of watch, Tuesday, July the thirteenth - he argued"}},
{"r1_d4_marty_somebody_normal","scanner",4,4,20,23,1,{"Marty","It's Tuesday night, I've had the scanner beside me since Sunday, and I've quit writing everything down - my hand won't do it anymore","Marty","I'll just let you hear this one, it's the sheriff's dispatcher - I don't know her last name, I wish I did","Dispatch","Knox County, time check, {time}, all units, it's a hot one tonight - check your tires, and check on each other","Dispatch","Nothing else to report, that's a good thing, tonight","Marty","That's all it was, I thought you ought to hear somebody say something ordinary"}},
{"r1_d4_riverside1_night_light","scanner",4,4,7,12,1,{"Riverside 1","Riverside 1 to Knox County, still at the house with my girls","Riverside 1","We came down out of the attic this morning, I cleared the house room by room, it's just us","Riverside 1","My oldest wants to talk on the radio, she says it's important","Girl","Hi, thank you for letting my daddy come home","Dispatch","You're very welcome, you look after him for me","Girl","I am, he had a bad dream, so I gave him my night-light","Riverside 1","Riverside 1, that's all the traffic - show us at home"}},
{"r1_d4_knox11_believe_it_with_me","scanner",4,4,0,4,2,{"Knox 11","Knox 11, Knox County, heavy gunfire from the Army line south of Muldraugh - machine guns, tracers going out over the fields","Dispatch","How long?","Knox 11","Twelve minutes now, it comes in bursts, then it stops, then it starts up again","Dispatch","Knox 11, can you see what they're shooting at?","Knox 11","Negative, too far and too dark - there's a crowd of them in the road ahead of me, all walking south toward the noise","Knox 11","I'm going to believe the Army's shooting at them, I'd appreciate it if you believed that with me","Dispatch","I believe it, Knox 11 - come on back in"}},
}
